  for (const v of pl.board) if (v !== u && v.id === 'choir_cantor') gainLife(p, 1);
  if (inPlay(u) && stats(u).p >= 5) for (const r of pl.relics) if (r.id === 'heart_old_grove') await draw(p, 1);
  await checkState();
