    const k = maxBy(enemies.filter(u => remH(u) <= harm), uval);
    if (k) return { uid: k.uid };
    if (q.players && q.players.includes(o)) return { p: o };
    const e = maxBy(enemies, uval); if (e) return { uid: e.uid };
